420	static inline bool mi_page_queue_len_is_atmost( mi_theap_t* theap, size_t block_size, long atmost) {
421	  if (atmost < 0) return false;
422	  mi_page_queue_t* const pq = mi_page_queue(theap,block_size);
423	  mi_assert_internal(pq!=NULL);
424	  return (pq->count <= (size_t)atmost);
425	}
