Program sketch:

```c
// xthread_free.c （示例代码）
#include <mimalloc.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdatomic.h>
#include <pthread.h>
#include <time.h>

#define N        (1000*1000)
#define RING_LOG (10)
#define RING_SIZE (1u<<RING_LOG)

static void*     ring[RING_SIZE];
static atomic_size_t r_head, r_tail;

static double now_sec(void) {
  struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
  return ts.tv_sec + ts.tv_nsec*1e-9;
}

static void produce(void* p) {
  size_t h = atomic_load_explicit(&r_head, memory_order_relaxed);
  while (h - atomic_load_explicit(&r_tail, memory_order_acquire) == RING_SIZE) { /* 满则自旋等待 */ }
  ring[h & (RING_SIZE-1)] = p;
  atomic_store_explicit(&r_head, h+1, memory_order_release);
}

static void* consumer(void* arg) {
  (void)arg;
  for (size_t i = 0; i < N; i++) {
    size_t t = atomic_load_explicit(&r_tail, memory_order_relaxed);
    while (t == atomic_load_explicit(&r_head, memory_order_acquire)) { /* 空则自旋等待 */ }
    void* p = ring[t & (RING_SIZE-1)];
    atomic_store_explicit(&r_tail, t+1, memory_order_release);
    mi_free(p);
  }
  return NULL;
}

int main(void) {
  double t0, t1;

  // 阶段一：同线程分配+释放（对照）
  t0 = now_sec();
  void** ps = (void**)mi_malloc(N*sizeof(void*));
  for (size_t i=0;i<N;i++) ps[i]=mi_malloc(32);
  for (size_t i=0;i<N;i++) mi_free(ps[i]);
  mi_free(ps);
  t1 = now_sec();
  printf("same-thread : %6.1f ms (%.0f ns/alloc+free pair)\n",(t1-t0)*1e3,(t1-t0)*1e9/N);

  // 阶段二：线程 A 分配，线程 B 释放
  atomic_store(&r_head,0); atomic_store(&r_tail,0);
  pthread_t tb; pthread_create(&tb,NULL,consumer,NULL);
  t0 = now_sec();
  for (size_t i=0;i<N;i++) produce(mi_malloc(32));
  pthread_join(tb,NULL);
  t1 = now_sec();
  printf("cross-thread: %6.1f ms (%.0f ns/alloc+free pair)\n",(t1-t0)*1e3,(t1-t0)*1e9/N);
  return 0;
}
```

Wait — the same-thread phase allocates and frees 32-byte blocks, then the cross phase re-allocates the same size — pages will be reused, fine. Note: the ring itself uses mi_malloc for ps array in phase 1; in phase 2 ring is static. Good.

One subtlety: in phase 2, thread B frees blocks owned by thread A's theap → cross-thread path (CAS). In phase 1, same path as u5-l1 (local). The comparison shows the CAS overhead + sharding benefit. Expected: cross-thread slightly slower or comparable (待本地验证). Also note debug build inflates with padding checks & memset freed; mention comparing release too.

Also note for observation: after pthread_join, thread B exits → its theap pages abandoned... thread B never allocated anything (its theap only did frees; mi_stat_free touched B's theap stats which auto-inits B's theap!). Actually mi_stat_free calls _mi_theap_default() which initializes thread B's theap on first free. So B gets a theap with no pages. Fine.

